"""Real FYG8 init operands and closed byte-level PID1 identity acceptance."""
from pathlib import Path
import shlex
import subprocess
import sys
import tempfile
import unittest

ROOT=Path(__file__).resolve().parents[1]
HERE=ROOT/'workspace/public/src/debian/s22plus_initramfs_h0'
sys.path.insert(0,str(ROOT/'workspace/public/src/scripts/revalidation'))
sys.path.insert(0,str(HERE))
import fyg8_vm

MINIMAL=b'/bin/sh\0/init\0'
# Operands recorded by the physical P425/P426 kernel at Run /init, followed
# by binfmt_script's interpreter insertion. This is not generated by the guard.
PHYSICAL=b'/bin/sh\0/init\0bootconfig\0nohyp_uart\0'


class Pid1Arguments(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temporary=tempfile.TemporaryDirectory(prefix='s22-pid1-argv-')
        cls.addClassCleanup(cls.temporary.cleanup)
        cls.binaries=[]
        for compiler,runner in (('gcc',[]),('aarch64-linux-gnu-gcc',['qemu-aarch64'])):
            binary=Path(cls.temporary.name)/compiler
            subprocess.run([compiler,'-static','-Os','-Wall','-Wextra','-Werror',
                '-Wno-unused-function','-ffunction-sections','-fdata-sections','-Wl,--gc-sections',
                '-I',str(HERE),'-I',str(ROOT/'workspace/public/src/native-init'),
                str(ROOT/'tests/s22plus_debian_pid1_argv_harness.c'),'-o',str(binary)],check=True)
            description=subprocess.check_output(['file',str(binary)],text=True)
            if compiler=='aarch64-linux-gnu-gcc':
                if 'ARM aarch64' not in description:raise AssertionError(description)
            cls.binaries.append((binary,runner))

    def accepted(self,value,expected,*,args=()):
        for binary,runner in self.binaries:
            with self.subTest(architecture=binary.name,value=value,args=args):
                result=subprocess.check_output([*runner,str(binary),*args],input=value)
                self.assertEqual(result,b'1\n' if expected else b'0\n')

    def test_minimal_and_observed_physical_tuple(self):
        for value in (MINIMAL,PHYSICAL):self.accepted(value,True)

    def test_representative_vm_preserves_physical_operands(self):
        parts=shlex.split(fyg8_vm.KERNEL_COMMAND_LINE)
        tail=parts[parts.index('--')+1:]
        value=MINIMAL+b'\0'.join(x.encode() for x in tail)+b'\0'
        self.assertEqual(value,PHYSICAL)
        self.accepted(value,True)

    def test_partial_reordered_extra_or_shell_command_is_rejected(self):
        for value in (MINIMAL+b'bootconfig\0',MINIMAL+b'nohyp_uart\0',
                MINIMAL+b'nohyp_uart\0bootconfig\0',PHYSICAL+b'bootconfig\0',
                PHYSICAL+b'extra\0',MINIMAL+b'\0',PHYSICAL+b'\0',
                b'/bin/sh\0-c\0/init\0',PHYSICAL.replace(b'/init\0',b'/other\0'),
                PHYSICAL.replace(b'/bin/sh\0',b'/usr/bin/sh\0'),b''):
            self.accepted(value,False)

    def test_truncation_and_single_byte_mutation_never_match(self):
        for value in (MINIMAL,PHYSICAL):
            for length in range(len(value)):
                shortened=value[:length]
                self.accepted(shortened,shortened==MINIMAL)
            for index in range(len(value)):
                changed=value[:index]+bytes([value[index]^1])+value[index+1:]
                self.accepted(changed,False)

    def test_read_failure_is_rejected(self):
        self.accepted(b'',False,args=('read-error',))


if __name__=='__main__':unittest.main()
